  function openSearch(){searchOpener=document.activeElement;const d=byId('search-dialog'),cats=['All','Messages','Chats','Agents','Channels','Projects','Files','Links'];byId('search-filters').replaceChildren(...cats.map(cat=>{const b=document.createElement('button');b.type='button';b.textContent=cat;b.dataset.searchCategory=cat;b.setAttribute('aria-pressed',String(cat==='All'));b.onclick=()=>{all('[data-search-category]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderSearch();};return b;}));byId('global-search').value='';renderSearch();d.showModal();byId('global-search').focus();}
